#include "ClothRuntime.h"
#include "SimulationMath.h"
#include <Windows.h>
#include <array>
#include <map>
#include <tuple>
namespace hs2 {
using namespace sim;
namespace {
std::array<float,3> Values(Vector3 v){return {v.x,v.y,v.z};}
void Append(std::vector<float>& values,Vector3 value){values.insert(values.end(),{value.x,value.y,value.z});}
float ScaleDistance(float value,float scale){return value>=std::numeric_limits<float>::max()*.5f?std::numeric_limits<float>::max():value*scale;}
}
struct NativeClothRuntime::Impl {
    struct Entry {std::shared_ptr<NativeSceneRenderer> Renderer;Parameter Data;std::vector<int> ParticleForVertex,FirstVertices;std::vector<float> Maximum,Separation;int Index=-1;NativeDeformedVertices Animation;};
    std::vector<Entry> Entries;std::filesystem::path Directory;bool Reset=true;std::vector<HMODULE> Modules;void* Scene=nullptr;
    const char*(__cdecl* Error)()=nullptr;void*(__cdecl* Create)()=nullptr;void(__cdecl* Destroy)(void*)=nullptr;
    int(__cdecl* Add)(void*,int,const float*,int,const uint32_t*,const float*,const float*,const float*)=nullptr;
    int(__cdecl* Update)(void*,int,const float*,const float*,const float*,const float*,const float*,int)=nullptr;
    int(__cdecl* Particles)(void*,int,int,const uint32_t*,int,const uint32_t*,int,const float*)=nullptr;
    int(__cdecl* Step)(void*,float)=nullptr;int(__cdecl* Read)(void*,int,int,float*)=nullptr;
    ~Impl(){for(auto& entry:Entries)entry.Renderer->SimulatedVertices.reset();if(Scene&&Destroy)Destroy(Scene);for(auto i=Modules.rbegin();i!=Modules.rend();++i)FreeLibrary(*i);}
    template<class T>void Bind(T& function,const char* name){function=reinterpret_cast<T>(GetProcAddress(Modules.back(),name));Require(function!=nullptr,"Native PhysX cloth export is missing.");}
    void Initialize(){if(Scene)return;if(Directory.empty()){std::wstring exe(32768,L'\0');auto n=GetModuleFileNameW(nullptr,exe.data(),static_cast<DWORD>(exe.size()));Require(n&&n<exe.size(),"Executable directory is unavailable.");exe.resize(n);Directory=std::filesystem::path(exe).parent_path()/"native/win-x64";}for(auto name:{L"PxFoundation_x64.dll",L"PhysX3Common_x64.dll",L"PxPvdSDK_x64.dll",L"PhysX3_x64.dll",L"HS2Manager.Physics.dll"}){auto path=std::filesystem::absolute(Directory/name).lexically_normal().make_preferred();auto module=LoadLibraryExW(path.c_str(),nullptr,LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR|LOAD_LIBRARY_SEARCH_DEFAULT_DIRS);Require(module!=nullptr,"Native PhysX cloth library is missing or cannot be loaded.");Modules.push_back(module);}Bind(Error,"hs2_cloth_error");Bind(Create,"hs2_cloth_create");Bind(Destroy,"hs2_cloth_destroy");Bind(Add,"hs2_cloth_add");Bind(Update,"hs2_cloth_update");Bind(Particles,"hs2_cloth_particles");Bind(Step,"hs2_cloth_step");Bind(Read,"hs2_cloth_read");Scene=Create();if(!Scene)throw std::runtime_error(Error()?Error():"Native PhysX cloth initialization failed.");}
    int Check(int value){if(value<0)throw std::runtime_error(Error()?Error():"Native PhysX cloth failed.");return value;}
};
NativeClothRuntime::NativeClothRuntime(NativeCharacterScene& scene,std::filesystem::path directory):impl_(std::make_unique<Impl>()){impl_->Directory=std::move(directory);for(auto& part:scene.Parts)for(auto& component:part->Definition->Components)if(component.Type=="Cloth"&&component.Data.Float("m_Enabled",1)!=0){auto found=std::find_if(scene.Renderers.begin(),scene.Renderers.end(),[&](auto& r){return r->Part==part->Definition&&r->Node->Name==component.Node;});Require(found!=scene.Renderers.end(),"Cloth renderer is missing.");Impl::Entry e;e.Renderer=*found;e.Data=component.Data;for(auto field:{"m_CapsuleColliders","m_SphereColliders"})Require(e.Data.Get(field).Children.empty(),"Cloth collider node mapping is not validated.");Require(LengthSquared(Vector(e.Data.Get("m_RandomAcceleration")))==0,"Cloth random acceleration requires its source seeded update.");std::map<std::tuple<float,float,float>,int> welded;for(int v=0;v<e.Renderer->Mesh->VertexCount;++v){auto& mesh=*e.Renderer->Mesh;auto key=std::tuple{mesh.Read(0,v,0),mesh.Read(0,v,1),mesh.Read(0,v,2)};auto [it,inserted]=welded.emplace(key,static_cast<int>(welded.size()));if(inserted)e.FirstVertices.push_back(v);e.ParticleForVertex.push_back(it->second);}auto& coefficients=e.Data.Get("m_Coefficients").Children;Require(coefficients.size()==e.FirstVertices.size(),"Cloth welded topology differs from authored coefficients.");for(auto& c:coefficients){e.Maximum.push_back(c.Float("maxDistance"));e.Separation.push_back(c.Float("collisionSphereDistance",std::numeric_limits<float>::max()));}impl_->Entries.push_back(std::move(e));}}
NativeClothRuntime::~NativeClothRuntime()=default;
bool NativeClothRuntime::HasCloth()const{return !impl_->Entries.empty();}
void NativeClothRuntime::Reset(){impl_->Reset=true;for(auto& entry:impl_->Entries)entry.Renderer->SimulatedVertices.reset();}
void NativeClothRuntime::Step(float seconds){auto& p=*impl_;if(p.Entries.empty())return;Require(std::isfinite(seconds)&&seconds>0&&seconds<=.333334f,"Invalid cloth time step.");p.Initialize();for(auto& e:p.Entries){auto& renderer=*e.Renderer;if(!renderer.Node->ActiveInHierarchy())continue;e.Animation=renderer.DeformAnimation();auto rotation=renderer.Node->Rotation(),inverse=Inverse(rotation);auto position=renderer.Node->Position();auto normalMatrix=renderer.Node->InverseWorldMatrix();Matrix4x4 transpose;DirectX::XMStoreFloat4x4(&transpose,DirectX::XMMatrixTranspose(DirectX::XMLoadFloat4x4(&normalMatrix)));std::vector<float> points,normals;for(auto v:e.FirstVertices){Append(points,Rotate(inverse,renderer.Node->TransformPoint(e.Animation.Positions[v])-position));Append(normals,Unit(Rotate(inverse,hs2::TransformVector(e.Animation.Normals[v],transpose)),{0,1,0}));}std::array<float,7> pose{position.x,position.y,position.z,rotation.x,rotation.y,rotation.z,rotation.w};auto rootWorld=(renderer.RootBone?renderer.RootBone:renderer.Node)->WorldMatrix();Vector3 rootScale{Length(hs2::TransformVector({1,0,0},rootWorld)),Length(hs2::TransformVector({0,1,0},rootWorld)),Length(hs2::TransformVector({0,0,1},rootWorld))};float scale=rootScale.x;if(e.Index<0){auto& mesh=*renderer.Mesh;std::vector<uint32_t> triangles;for(auto& sub:mesh.Submeshes){Require(sub.Topology==0,"Cloth requires triangles.");for(int i=sub.FirstIndex;i<sub.FirstIndex+sub.IndexCount;++i)triangles.push_back(static_cast<uint32_t>(e.ParticleForVertex[sub.BaseVertex+mesh.Index(i)]));}auto& d=e.Data;std::array<float,15> parameters{d.Float("m_StretchingStiffness",1),d.Float("m_BendingStiffness",1),d.Float("m_Damping"),d.Float("m_Friction",.5f),d.Float("m_CollisionMassScale"),d.Float("m_UseContinuousCollision",1),d.Float("m_SolverFrequency",120),d.Float("m_StiffnessFrequency",10),d.Float("m_UseTethers",1),d.Float("m_SleepThreshold",.1f),d.Float("m_SelfCollisionDistance"),d.Float("m_SelfCollisionStiffness",1),d.Float("m_WorldVelocityScale",.5f),d.Float("m_WorldAccelerationScale",1),d.Float("m_UseGravity",1)};std::vector<float> maximum,cooked;for(auto v:e.Maximum)maximum.push_back(ScaleDistance(v,scale));for(auto v:e.FirstVertices)Append(cooked,Product({mesh.Read(0,v,0),mesh.Read(0,v,1),mesh.Read(0,v,2)},rootScale));e.Index=p.Check(p.Add(p.Scene,static_cast<int>(e.FirstVertices.size()),cooked.data(),static_cast<int>(triangles.size()),triangles.data(),maximum.data(),parameters.data(),pose.data()));std::vector<uint32_t> self,virtualIndices;std::vector<float> weights;for(auto& v:d.Get("m_SelfAndInterCollisionIndices").Children)self.push_back(static_cast<uint32_t>(v.Number));for(auto& v:d.Get("m_VirtualParticleIndices").Children)virtualIndices.push_back(static_cast<uint32_t>(v.Number));for(auto& v:d.Get("m_VirtualParticleWeights").Children)Append(weights,Vector(v));Require(virtualIndices.size()%4==0,"Cloth virtual index tuple is incomplete.");p.Check(p.Particles(p.Scene,e.Index,static_cast<int>(self.size()),self.data(),static_cast<int>(virtualIndices.size()/4),virtualIndices.data(),static_cast<int>(weights.size()/3),weights.data()));}std::vector<float> separation;for(auto v:e.Separation)separation.push_back(ScaleDistance(v,scale));auto acceleration=Values(Vector(e.Data.Get("m_ExternalAcceleration")));p.Check(p.Update(p.Scene,e.Index,points.data(),normals.data(),separation.data(),pose.data(),acceleration.data(),p.Reset?1:0));}
    p.Check(p.Step(p.Scene,seconds));p.Reset=false;for(auto& e:p.Entries){auto& renderer=*e.Renderer;if(e.Index<0||!renderer.Node->ActiveInHierarchy())continue;std::vector<float> points(e.FirstVertices.size()*3);p.Check(p.Read(p.Scene,e.Index,static_cast<int>(e.FirstVertices.size()),points.data()));auto rotation=renderer.Node->Rotation();auto position=renderer.Node->Position();NativeDeformedVertices simulated;simulated.Positions.resize(e.ParticleForVertex.size());simulated.Normals.resize(e.ParticleForVertex.size());simulated.Tangents=e.Animation.Tangents;for(size_t i=0;i<simulated.Positions.size();++i){auto at=e.ParticleForVertex[i]*3;auto world=Rotate(rotation,{points[at],points[at+1],points[at+2]})+position;simulated.Positions[i]=renderer.Node->InverseTransformPoint(world);}std::vector<Vector3> normals(e.FirstVertices.size());auto& mesh=*renderer.Mesh;for(auto& sub:mesh.Submeshes)for(int i=sub.FirstIndex;i<sub.FirstIndex+sub.IndexCount;i+=3){auto a=sub.BaseVertex+mesh.Index(i),b=sub.BaseVertex+mesh.Index(i+1),c=sub.BaseVertex+mesh.Index(i+2);auto normal=Cross(simulated.Positions[b]-simulated.Positions[a],simulated.Positions[c]-simulated.Positions[a]);normals[e.ParticleForVertex[a]]+=normal;normals[e.ParticleForVertex[b]]+=normal;normals[e.ParticleForVertex[c]]+=normal;}for(size_t i=0;i<simulated.Normals.size();++i)simulated.Normals[i]=Unit(normals[e.ParticleForVertex[i]],{0,1,0});renderer.SimulatedVertices=std::move(simulated);}}
}
